def sembrar_metodo_qr_mercadopago(apps, schema_editor):
    """Método global 'QR Mercado Pago' -- si ya existía con ese nombre exacto
    (poco probable, pero MetodoPago.nombre es free-text), solo le prende el
    flag; si no existía, lo crea. No se borra en el reverse (quedaría
    huérfano de aranceles ya configurados)."""
    MetodoPago = apps.get_model('inventario', 'MetodoPago')
    metodo, _creado = MetodoPago.objects.get_or_create(
        nombre='QR Mercado Pago',
        defaults={'es_financiero': True, 'requiere_integracion_mp': True, 'activo': True},
    )
    if not _creado and not metodo.requiere_integracion_mp:
        metodo.requiere_integracion_mp = True
        metodo.es_financiero = True
        metodo.save(update_fields=['requiere_integracion_mp', 'es_financiero'])


